package com.example.lifeos.ui.screens.belajar.bahasainggris.tatabahasa

import com.example.lifeos.ui.screens.belajar.common.QuizQuestion

val tataBahasaQuestionBank: List<QuizQuestion> = listOf(
    QuizQuestion(1, "She ___ to school every day.", listOf("goes", "go", "going", "gone"), 0, "Untuk subjek tunggal (she) dalam simple present tense, kata kerja ditambah -s/-es: 'goes'."),
    QuizQuestion(2, "They ___ football yesterday.", listOf("played", "play", "plays", "playing"), 0, "'Yesterday' menunjukkan waktu lampau, jadi memakai simple past tense: 'played'."),
    QuizQuestion(3, "I saw ___ elephant at the zoo.", listOf("an", "a", "the", "some"), 0, "Kata 'elephant' dimulai dengan huruf vokal (e), jadi memakai artikel 'an'."),
    QuizQuestion(4, "The cat is sleeping ___ the box.", listOf("in", "on", "at", "to"), 0, "'In' dipakai untuk menunjukkan sesuatu berada di dalam suatu ruang/wadah, seperti kotak."),
    QuizQuestion(5, "There are three ___ on the table.", listOf("apples", "apple", "an apple", "apples's"), 0, "Karena jumlahnya lebih dari satu (three), kata benda 'apple' harus dijadikan jamak: 'apples'."),
    QuizQuestion(6, "This box is ___ than that one.", listOf("bigger", "big", "biggest", "more big"), 0, "Untuk membandingkan dua hal, gunakan bentuk komparatif: 'bigger' (dari 'big')."),
    QuizQuestion(7, "___ is your name?", listOf("What", "Who", "Where", "When"), 0, "'What' dipakai untuk menanyakan nama/benda, bukan orang (who) atau tempat (where)."),
    QuizQuestion(8, "He ___ his homework already.", listOf("has finished", "have finished", "finish", "finishing"), 0, "Untuk subjek tunggal (he) dalam present perfect tense, memakai 'has' + past participle: 'has finished'."),
    QuizQuestion(9, "We ___ going to the beach tomorrow.", listOf("are", "is", "am", "be"), 0, "Subjek 'we' (jamak) memakai 'are' dalam kalimat present continuous untuk rencana masa depan."),
    QuizQuestion(10, "My father ___ a doctor.", listOf("is", "are", "am", "be"), 0, "Subjek tunggal 'my father' memakai 'is'."),
    QuizQuestion(11, "I don't have ___ money with me.", listOf("any", "some", "a", "an"), 0, "Dalam kalimat negatif, kita memakai 'any', bukan 'some'."),
    QuizQuestion(12, "This is the ___ movie I have ever seen.", listOf("best", "good", "better", "goodest"), 0, "Untuk superlatif (paling), gunakan 'best' (bentuk superlatif dari 'good')."),
    QuizQuestion(13, "She is taller than ___.", listOf("me", "I", "my", "mine"), 0, "Setelah kata 'than' dalam perbandingan, memakai kata ganti objek: 'me', bukan 'I'."),
    QuizQuestion(14, "___ you like some tea?", listOf("Would", "Do", "Are", "Does"), 0, "'Would you like...?' adalah cara sopan untuk menawarkan sesuatu."),
    QuizQuestion(15, "The children ___ playing in the park now.", listOf("are", "is", "am", "be"), 0, "Subjek jamak 'the children' memakai 'are' dalam present continuous."),
    QuizQuestion(16, "I have lived here ___ 2015.", listOf("since", "for", "from", "at"), 0, "'Since' dipakai untuk titik waktu tertentu (misal tahun 2015), sedangkan 'for' dipakai untuk durasi (misal 'for 5 years')."),
    QuizQuestion(17, "She speaks English very ___.", listOf("well", "good", "best", "better"), 0, "'Well' adalah kata keterangan (adverb) yang menerangkan kata kerja 'speaks', sedangkan 'good' adalah kata sifat (adjective)."),
    QuizQuestion(18, "___ of the two books is more interesting?", listOf("Which", "What", "Who", "Where"), 0, "'Which' dipakai untuk memilih di antara pilihan terbatas (dua buku), lebih tepat daripada 'what'."),
    QuizQuestion(19, "He can't swim, and ___ can I.", listOf("neither", "either", "so", "too"), 0, "'Neither can I' dipakai untuk menyatakan kesamaan dalam kalimat negatif."),
    QuizQuestion(20, "By the time we arrived, the movie ___ already started.", listOf("had", "has", "have", "was"), 0, "Past perfect tense ('had started') dipakai untuk kejadian yang terjadi sebelum kejadian lampau lainnya (kita tiba)."),
)
